"""Original background music generated by code (no samples, no license needed).
120 BPM electronic racing track synced to the video timeline (15 s @ 30 fps):
F1 start beeps -> lights-out drop -> beat with bass/arp -> whooshes on each transition -> final hit.
Output: public/audio/musica.wav (48 kHz stereo). Requires only numpy.
"""
import wave
import numpy as np

SR = 48000
DUR = 15.0
N = int(SR * DUR)
FPS = 30
rng = np.random.default_rng(7)
L = np.zeros(N); R = np.zeros(N)

def t_(d): return np.arange(int(d * SR)) / SR

def add(sig, at, pan=0.0, gain=1.0):
    i = int(at * SR)
    if i >= N: return
    sig = sig[: N - i] * gain
    L[i:i + len(sig)] += sig * np.sqrt(0.5 * (1 - pan))
    R[i:i + len(sig)] += sig * np.sqrt(0.5 * (1 + pan))

def env(n, a=0.005, d=0.2):
    t = np.arange(n) / SR
    return np.minimum(1, t / max(a, 1e-4)) * np.exp(-t / d)

def saw(f, d, harm=18):
    t = t_(d); s = np.zeros_like(t)
    for k in range(1, harm + 1):
        if f * k > SR / 2.2: break
        s += np.sin(2 * np.pi * f * k * t) / k
    return s * 0.6

def kick():
    t = t_(0.35); f = 45 + 110 * np.exp(-t * 35)
    return np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 9)

def snare():
    t = t_(0.22)
    return (rng.standard_normal(len(t)) * 0.6 + np.sin(2 * np.pi * 190 * t) * 0.5) * np.exp(-t * 18)

def hat():
    t = t_(0.06); n = rng.standard_normal(len(t))
    n = n - np.convolve(n, np.ones(4) / 4, 'same')  # crude highpass
    return n * np.exp(-t * 70)

def noise_sweep(d, rise=True):
    n = rng.standard_normal(int(d * SR))
    spec = np.fft.rfft(n); fr = np.fft.rfftfreq(len(n), 1 / SR)
    spec *= np.exp(-((np.log(fr + 1) - np.log(3000)) ** 2) / 2.5)
    s = np.fft.irfft(spec, len(n)); s /= np.abs(s).max()
    e = np.sin(np.linspace(0, np.pi, len(s))) ** 2
    return s * e

def note(m): return 440 * 2 ** ((m - 69) / 12)

# ---- 0 - 1.27 s: F1 start lights (beeps at frames 4,10,16,22,28) + engine hum
for k in range(5):
    t = t_(0.16)
    add(np.sin(2 * np.pi * 1000 * t) * env(len(t), 0.003, 0.08), (4 + 6 * k) / FPS, gain=0.35)
t = t_(1.3); f = 55 + 60 * (t / 1.3) ** 2
hum = np.sin(2 * np.pi * np.cumsum(f) / SR) + 0.5 * np.sin(2 * np.pi * np.cumsum(2 * f) / SR)
add(hum * np.linspace(0, 1, len(hum)) ** 2, 0, gain=0.25)
add(noise_sweep(1.1), 0.2, gain=0.25)

DROP = 38 / FPS  # lights out
BEAT = 0.5       # 120 BPM
add(kick(), DROP, gain=1.0)
add(noise_sweep(1.6), DROP, gain=0.3)

# ---- Groove from the drop until 14 s
chords = [(57, [69, 72, 76]), (53, [65, 69, 72]), (48, [64, 67, 72]), (55, [67, 71, 74])]  # Am F C G
t0 = DROP; END = 14.0
beat = 0
while t0 + beat * BEAT < END:
    at = t0 + beat * BEAT
    bar = int(beat // 4) % 4
    root, triad = chords[bar]
    add(kick(), at, gain=0.95)
    add(hat(), at + BEAT / 2, pan=0.3, gain=0.35)
    add(hat(), at + BEAT / 4, pan=-0.3, gain=0.12)
    if beat % 4 in (1, 3): add(snare(), at, gain=0.45)
    for h in range(2):  # 8th-note bass
        b = saw(note(root - 12 + (12 if h else 0)), BEAT / 2 * 0.9, 12)
        add(b * env(len(b), 0.004, 0.18), at + h * BEAT / 2, gain=0.32)
    for q in range(4):  # 16th arpeggio
        m = triad[(beat * 4 + q) % 3] + (12 if q == 3 else 0)
        a = saw(note(m), 0.12, 8)
        add(a * env(len(a), 0.002, 0.05), at + q * BEAT / 4, pan=0.4 * (-1) ** q, gain=0.12)
    if beat % 4 == 0:  # pad
        for m in triad:
            p = saw(note(m - 12), BEAT * 4, 6) * np.sin(np.linspace(0, np.pi, int(BEAT * 4 * SR)))
            add(p, at, gain=0.05)
    beat += 1

# ---- Whooshes on scene transitions (frames 85, 185, 285, 360; 15 frames each)
for f in (85, 185, 285, 360):
    add(noise_sweep(0.9), f / FPS - 0.35, pan=0.0, gain=0.55)

# ---- Final hit + ringing chord (checkered flag)
add(kick(), END, gain=1.1)
for m in (57, 64, 69, 72, 76):
    s = saw(note(m), DUR - END, 10) * np.exp(-t_(DUR - END) * 2.2)
    add(s, END, gain=0.12)
add(noise_sweep(1.0), END, gain=0.3)

# ---- Master: soft limit, fades, normalize
mix = np.stack([L, R], 1)
mix = np.tanh(mix * 1.4)
fade = np.ones(N); fade[-int(0.6 * SR):] = np.linspace(1, 0, int(0.6 * SR))
mix *= fade[:, None]
mix /= np.abs(mix).max() / 0.89
pcm = (mix * 32767).astype('<i2')
with wave.open('public/audio/musica.wav', 'wb') as w:
    w.setnchannels(2); w.setsampwidth(2); w.setframerate(SR); w.writeframes(pcm.tobytes())
print('public/audio/musica.wav', DUR, 's')
